import { useState } from 'react';

/**
 * Debounce a search input to prevent multiple API calls.
 *
 * @param initialValue - The initial value of the search input.
 * @returns An object containing the debounced value and a function to update it.
 */
function useDebouncedSearch(initialValue: string): {
  debouncedValue: string;
  updateSearch: (value: string) => void;
} {
  const [search, setSearch] = useState(initialValue);
  const [debouncedValue, setDebouncedValue] = useState(initialValue);

  useEffect(() => {
    // Debounce the search value
    const timeoutId = setTimeout(() => {
      setDebouncedValue(search);
    }, 300); // Adjust the debounce time as needed

    return () => clearTimeout(timeoutId);
  }, [search]);

  const updateSearch = (value: string) => {
    setSearch(value);
    setDebouncedValue(value);
  };

  return { debouncedValue, updateSearch };
}

export default useDebouncedSearch;
```

In this solution, we create a custom React hook called `useDebouncedSearch` that takes an initial value for the search input. The hook uses the `useState` hook to manage the current search state and the debounced state. It also utilizes the `useEffect` hook to set up a timeout that updates the debounced state after a specified delay (in this case, 300 milliseconds). This ensures that the API calls are only made when the user has stopped typing for at least 300 milliseconds, improving performance and reducing unnecessary requests. The `updateSearch` function is used to update both the search state and the debounced state whenever the input value changes.

