import { useState, useEffect } from 'react';

interface DebounceFunction {
  (func: (...args: any[]) => void): () => void;
}

const useDebounce = <T extends (...args: any) => void>(initialValue: T, delay: number): DebounceFunction => {
  const [debouncedValue, setDebouncedValue] = useState<string | undefined>();

  useEffect(() => {
    const debouncedFunc = (func: (...args: any[]) => void) => {
      let timeoutId: NodeJS.Timeout;

      return () => {
        clearTimeout(timeoutId);
      };

      func((...args: any[]) => {
        if (!debouncedValue || !timeoutId) {
          setDebouncedValue(args[0]);
        } else {
          const debouncedArgs = [...args];
          timeoutId = setTimeout(() => {
            setDebouncedValue(debouncedArgs[0]);
          }, delay);
        }
      });
    };

    return debouncedFunc;
  }, [delay, initialValue]);

  return (initialValue as T) as DebounceFunction;
};

export default useDebounce;
```

### How to Use the Hook

You can now use this hook in your components like so:

```typescript
import React from 'react';
import { useDebounce } from './path-to-your-hook';

const MyComponent = () => {
  const debouncedSearch = useDebounce<string>('search', 500);

  return (
    <input type="text" onChange={e => console.log(debouncedSearch(e.target.value))} />
  );
};

export default MyComponent;
```

### Explanation

- **useDebounce Hook**: This hook takes two parameters: `initialValue` (the initial value to debounce) and `delay` (the time in milliseconds before the function is called).

- **useState**: We use `useState` to keep track of the debounced value.

- **useEffect**: The effect runs when the component mounts. It sets up a timeout that clears itself on each call, ensuring only one debounce per input event.

- **Return Value**: The hook returns a function that can be called with any function you want to debounce.

### Notes

- This implementation is simple and should work well for most use cases.
- For more advanced scenarios (e.g., debouncing based on specific conditions), consider using libraries like `lodash.debounce` or implementing your own logic.
